<script setup>import FlowShell from './FlowShell.vue';import {state,navigate,confirm,createHelp} from './app-state.js';function help(){confirm('发起模拟求助','仅创建本地演示求助，不会真实定位或联系工作人员。',()=>{createHelp();navigate('tour-help')})}</script>
<template><FlowShell class="paper-page paper-final" title="智能出行">
  <view class="paper-hero paper-photo-hero"><image class="paper-cover" src="/static/travel/park.jpg" mode="aspectFill"/><view class="paper-hero-caption"><text class="paper-title">旅游，按自己的节奏</text><text class="paper-subtitle">安排这次出游，查看沿途设施，记录走过的路线。</text></view></view>
  <view class="paper-card"><text class="paper-body">从这里开始，安排好自己的游览节奏。</text><button class="paper-primary paper-final-cta" @click="navigate(state.tour&&!state.tour.ended?'tour-ongoing':state['trip-record']?'trip-record':'plan')">{{state.tour&&!state.tour.ended?'继续游览':state['trip-record']?'查看记录':'这次怎么逛'}}</button></view>
  <view class="paper-card"><text class="paper-heading">行前安排</text><button v-for="x in [['scenic-detail','景区详情','mountain'],['plan','这次怎么逛','flag']]" :key="x[0]" class="paper-field" @click="navigate(x[0])"><view class="paper-disc"><image :src="'/static/outing/icons/'+x[2]+'.svg'"/></view><text class="paper-copy paper-value">{{x[1]}}</text><image class="paper-chevron" src="/static/outing/icons/back.svg"/></button></view>
  <view class="paper-card"><text class="paper-heading">游中支持</text><button class="paper-field" @click="navigate('tour-facilities')"><view class="paper-disc"><image src="/static/outing/icons/seat.svg"/></view><text class="paper-copy paper-value">附近设施</text><image class="paper-chevron" src="/static/outing/icons/back.svg"/></button><button class="paper-field" @click="help"><view class="paper-disc paper-disc-warm"><image src="/static/outing/icons/headset.svg"/></view><text class="paper-copy paper-value">找人帮忙</text><image class="paper-chevron" src="/static/outing/icons/back.svg"/></button></view>
</FlowShell></template>
<style src="./paper.css"></style>
